local HardyHoleMaker = {}
local PRODUCTS = {
    iron_hardyhole = { name = "Železni luknja za trdo orodje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni luknja za trdo orodje za kovace." },
    bronze_hardyhole = { name = "Bronast luknja za trdo orodje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast luknja za trdo orodje za kovace." },
    silver_hardyhole = { name = "Srebrn luknja za trdo orodje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn luknja za trdo orodje za kovace." },
    gilded_hardyhole = { name = "Pozlačen luknja za trdo orodje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen luknja za trdo orodje za kovace." },
    jewel_set_hardyhole = { name = "Draguljast luknja za trdo orodje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast luknja za trdo orodje za kovace." },
    royal_sovereign_hardyhole = { name = "Kraljevski suveren luknja za trdo orodje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren luknja za trdo orodje z biseri za krono." },
}
local BUILDINGS = {
    hardyhole_workshop = { name = "Hardyhole delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    hardyhole_house = { name = "Hardyhole hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_hardyhole_atelier = { name = "Mojstrski hardyhole atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_hardyhole_palace = { name = "Suverena hardyhole palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HardyHoleMaker.ironStock=16; HardyHoleMaker.bronzeStock=12; HardyHoleMaker.woodStock=12; HardyHoleMaker.leatherStock=8; HardyHoleMaker.silverStock=8; HardyHoleMaker.goldStock=6; HardyHoleMaker.jewelStock=4; HardyHoleMaker.pearlStock=4
HardyHoleMaker.productStock = {}; HardyHoleMaker.buildings = {}; HardyHoleMaker.maker = nil; HardyHoleMaker.activeMaking = {}; HardyHoleMaker.totalProducts = 0; HardyHoleMaker.dayTimer = 0
function HardyHoleMaker.init() HardyHoleMaker.ironStock=16; HardyHoleMaker.bronzeStock=12; HardyHoleMaker.woodStock=12; HardyHoleMaker.leatherStock=8; HardyHoleMaker.silverStock=8; HardyHoleMaker.goldStock=6; HardyHoleMaker.jewelStock=4; HardyHoleMaker.pearlStock=4; HardyHoleMaker.productStock={}; HardyHoleMaker.buildings={}; HardyHoleMaker.maker=nil; HardyHoleMaker.activeMaking={}; HardyHoleMaker.totalProducts=0; HardyHoleMaker.dayTimer=0; print("[HardyHoleMaker] Royal Hardy Hole Maker System initialized (6 products, 4 buildings)") end
function HardyHoleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HardyHoleMaker.maker={name=n or ("Luknjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Luknjar najet: %s (spretnost: %d)",HardyHoleMaker.maker.name,s),"success") end; return true end
function HardyHoleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HardyHoleMaker.build(id) local ok,e=HardyHoleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HardyHoleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HardyHoleMaker.getQualityBonus() local b=0; for _,bd in ipairs(HardyHoleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HardyHoleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HardyHoleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HardyHoleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HardyHoleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HardyHoleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HardyHoleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HardyHoleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HardyHoleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HardyHoleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HardyHoleMaker.buildings==0 then return false,"Potrebna luknjarska delavnica" end; if not HardyHoleMaker.maker then return false,"Potreben luknjar" end; return true end
function HardyHoleMaker.make(pt,qty) qty=qty or 1; local ok,e=HardyHoleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HardyHoleMaker.ironStock=HardyHoleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HardyHoleMaker.bronzeStock=HardyHoleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HardyHoleMaker.woodStock=HardyHoleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HardyHoleMaker.leatherStock=HardyHoleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HardyHoleMaker.silverStock=HardyHoleMaker.silverStock-d.silverCost*qty end; if d.goldCost then HardyHoleMaker.goldStock=HardyHoleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HardyHoleMaker.jewelStock=HardyHoleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HardyHoleMaker.pearlStock=HardyHoleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HardyHoleMaker.maker then t=math.max(1,t-math.floor(HardyHoleMaker.maker.skill/13)) end; table.insert(HardyHoleMaker.activeMaking,{id="hardyhole_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HardyHoleMaker.completeMaking(m) local q=1.0+(HardyHoleMaker.getQualityBonus()/100); if HardyHoleMaker.maker then q=q+(HardyHoleMaker.maker.skill/140) end; q=math.min(2.5,q); HardyHoleMaker.productStock[m.productType]=(HardyHoleMaker.productStock[m.productType] or 0)+m.quantity; HardyHoleMaker.totalProducts=HardyHoleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HardyHoleMaker.maker then HardyHoleMaker.maker.itemsMade=HardyHoleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HardyHoleMaker.maker.skill=math.min(100,HardyHoleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Luknja izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hardyhole.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HardyHoleMaker.update(dt) if not _G.state then return end; HardyHoleMaker.dayTimer=HardyHoleMaker.dayTimer+dt; if HardyHoleMaker.dayTimer>=30 then HardyHoleMaker.dayTimer=0; for i=#HardyHoleMaker.activeMaking,1,-1 do local m=HardyHoleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HardyHoleMaker.completeMaking(m); table.remove(HardyHoleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HardyHoleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HardyHoleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HardyHoleMaker.getStats() return {ironStock=HardyHoleMaker.ironStock,bronzeStock=HardyHoleMaker.bronzeStock,woodStock=HardyHoleMaker.woodStock,leatherStock=HardyHoleMaker.leatherStock,silverStock=HardyHoleMaker.silverStock,goldStock=HardyHoleMaker.goldStock,jewelStock=HardyHoleMaker.jewelStock,pearlStock=HardyHoleMaker.pearlStock,productStock=HardyHoleMaker.productStock,numBuildings=#HardyHoleMaker.buildings,hasMaker=HardyHoleMaker.maker~=nil,makerName=HardyHoleMaker.maker and HardyHoleMaker.maker.name or "—",makerSkill=HardyHoleMaker.maker and HardyHoleMaker.maker.skill or 0,activeMaking=#HardyHoleMaker.activeMaking,totalProducts=HardyHoleMaker.totalProducts} end
return HardyHoleMaker
